18	package org.apache.hadoop.hdfs.tools.offlineImageViewer;
19	
20	import org.apache.hadoop.fs.Path;
21	import org.apache.hadoop.fs.permission.PermissionStatus;
22	import org.apache.hadoop.hdfs.protocol.HdfsConstants;
23	import org.apache.hadoop.hdfs.server.namenode.FsImageProto.INodeSection.INode;
24	import org.apache.hadoop.hdfs.server.namenode.FsImageProto.INodeSection.INodeDirectory;
25	import org.apache.hadoop.hdfs.server.namenode.FsImageProto.INodeSection.INodeFile;
26	import org.apache.hadoop.hdfs.server.namenode.FsImageProto.INodeSection.INodeSymlink;
27	
28	import java.io.IOException;
29	import java.io.PrintStream;
30	import java.text.SimpleDateFormat;
31	
32	/**
33	 * A PBImageDelimitedTextWriter generates a text representation of the PB fsimage,
34	 * with each element separated by a delimiter string.  All of the elements
35	 * common to both inodes and inodes-under-construction are included. When
36	 * processing an fsimage with a layout version that did not include an
37	 * element, such as AccessTime, the output file will include a column
38	 * for the value, but no value will be included.
39	 *
40	 * Individual block information for each file is not currently included.
41	 *
42	 * The default delimiter is tab, as this is an unlikely value to be included in
43	 * an inode path or other text metadata. The delimiter value can be via the
44	 * constructor.
45	 */
46	public class PBImageDelimitedTextWriter extends PBImageTextWriter {
47	  private static final String DATE_FORMAT = "yyyy-MM-dd HH:mm";
48	  private boolean printStoragePolicy;
49	
50	  static class OutputEntryBuilder {
51	    private final SimpleDateFormat dateFormatter =
52	        new SimpleDateFormat(DATE_FORMAT);
53	
54	    private PBImageDelimitedTextWriter writer;
55	    private Path path;
56	    private int replication = 0;
57	    private long modificationTime;
58	    private long accessTime = 0;
59	    private long preferredBlockSize = 0;
60	    private int blocksCount = 0;
61	    private long fileSize = 0;
62	    private long nsQuota = 0;
63	    private long dsQuota = 0;
64	    private int storagePolicy = 0;
65	
66	    private String dirPermission = "-";
67	    private PermissionStatus permissionStatus;
68	    private String aclPermission = "";
69	
70	    OutputEntryBuilder(PBImageDelimitedTextWriter writer, INode inode) {
71	      this.writer = writer;
72	      switch (inode.getType()) {
73	      case FILE:
74	        INodeFile file = inode.getFile();
75	        replication = file.getReplication();
76	        modificationTime = file.getModificationTime();
77	        accessTime = file.getAccessTime();
78	        preferredBlockSize = file.getPreferredBlockSize();
79	        blocksCount = file.getBlocksCount();
80	        fileSize = FSImageLoader.getFileSize(file);
81	        permissionStatus = writer.getPermission(file.getPermission());
82	        if (file.hasAcl() && file.getAcl().getEntriesCount() > 0){
83	          aclPermission = "+";
84	        }
85	        storagePolicy = file.getStoragePolicyID();
86	        break;
87	      case DIRECTORY:
88	        INodeDirectory dir = inode.getDirectory();
89	        modificationTime = dir.getModificationTime();
90	        nsQuota = dir.getNsQuota();
91	        dsQuota = dir.getDsQuota();
92	        dirPermission = "d";
93	        permissionStatus = writer.getPermission(dir.getPermission());
94	        if (dir.hasAcl() && dir.getAcl().getEntriesCount() > 0) {
95	          aclPermission = "+";
96	        }
97	        storagePolicy = writer.getStoragePolicy(dir.getXAttrs());
98	        break;
99	      case SYMLINK:
100	        INodeSymlink s = inode.getSymlink();
101	        modificationTime = s.getModificationTime();
102	        accessTime = s.getAccessTime();
103	        permissionStatus = writer.getPermission(s.getPermission());
104	        storagePolicy = HdfsConstants.BLOCK_STORAGE_POLICY_ID_UNSPECIFIED;
105	        break;
106	      default:
107	        break;
108	      }
109	    }
110	
111	    void setPath(Path path) {
112	      this.path = path;
113	    }
114	
115	    public String build() {
116	      assert permissionStatus != null : "The PermissionStatus is null!";
117	      assert permissionStatus.getUserName() != null : "User name is null!";
118	      assert permissionStatus.getGroupName() != null : "Group name is null!";
119	
120	      StringBuffer buffer = new StringBuffer();
121	      writer.append(buffer, path.toString());
122	      writer.append(buffer, replication);
123	      writer.append(buffer, dateFormatter.format(modificationTime));
124	      writer.append(buffer, dateFormatter.format(accessTime));
125	      writer.append(buffer, preferredBlockSize);
126	      writer.append(buffer, blocksCount);
127	      writer.append(buffer, fileSize);
128	      writer.append(buffer, nsQuota);
129	      writer.append(buffer, dsQuota);
130	      writer.append(buffer, dirPermission +
131	          permissionStatus.getPermission().toString() + aclPermission);
132	      writer.append(buffer, permissionStatus.getUserName());
133	      writer.append(buffer, permissionStatus.getGroupName());
134	      if (writer.printStoragePolicy) {
135	        writer.append(buffer, storagePolicy);
136	      }
137	      return buffer.substring(1);
138	    }
139	  }
140	
141	  PBImageDelimitedTextWriter(PrintStream out, String delimiter, String tempPath)
142	      throws IOException {
143	    this(out, delimiter, tempPath, false);
144	  }
145	
146	  PBImageDelimitedTextWriter(PrintStream out, String delimiter,
147	                             String tempPath, boolean printStoragePolicy)
148	      throws IOException {
149	    this(out, delimiter, tempPath, printStoragePolicy, 1, "-");
150	  }
151	
152	  PBImageDelimitedTextWriter(PrintStream out, String delimiter,
153	      String tempPath, boolean printStoragePolicy, int threads,
154	      String parallelOut) throws IOException {
155	    super(out, delimiter, tempPath, threads, parallelOut);
156	    this.printStoragePolicy = printStoragePolicy;
157	  }
158	
159	  @Override
160	  public String getEntry(String parent, INode inode) {
161	    OutputEntryBuilder entryBuilder =
162	        new OutputEntryBuilder(this, inode);
163	
164	    String inodeName = inode.getName().toStringUtf8();
165	    Path path = new Path(parent.isEmpty() ? "/" : parent,
166	      inodeName.isEmpty() ? "/" : inodeName);
167	    entryBuilder.setPath(path);
168	
169	    return entryBuilder.build();
170	  }
171	
172	  @Override
173	  public String getHeader() {
174	    StringBuffer buffer = new StringBuffer();
175	    buffer.append("Path");
176	    append(buffer, "Replication");
177	    append(buffer, "ModificationTime");
178	    append(buffer, "AccessTime");
179	    append(buffer, "PreferredBlockSize");
180	    append(buffer, "BlocksCount");
181	    append(buffer, "FileSize");
182	    append(buffer, "NSQUOTA");
183	    append(buffer, "DSQUOTA");
184	    append(buffer, "Permission");
185	    append(buffer, "UserName");
186	    append(buffer, "GroupName");
187	    if (printStoragePolicy) {
188	      append(buffer, "StoragePolicyId");
189	    }
190	    return buffer.toString();
191	  }
192	
193	  @Override
194	  public void afterOutput() {
195	    // do nothing
196	  }
197	}
