39	/**
40	 * OfflineImageViewerPB to dump the contents of an Hadoop image file to XML or
41	 * the console. Main entry point into utility, either via the command line or
42	 * programmatically.
43	 */
44	@InterfaceAudience.Private
45	public class OfflineImageViewerPB {
46	  private static final String HELP_OPT = "-h";
47	  private static final String HELP_LONGOPT = "--help";
48	  public static final Logger LOG =
49	      LoggerFactory.getLogger(OfflineImageViewerPB.class);
50	
51	  private final static String usage = "Usage: bin/hdfs oiv [OPTIONS] -i INPUTFILE -o OUTPUTFILE\n"
52	      + "Offline Image Viewer\n"
53	      + "View a Hadoop fsimage INPUTFILE using the specified PROCESSOR,\n"
54	      + "saving the results in OUTPUTFILE.\n"
55	      + "\n"
56	      + "The oiv utility will attempt to parse correctly formed image files\n"
57	      + "and will abort fail with mal-formed image files.\n"
58	      + "\n"
59	      + "The tool works offline and does not require a running cluster in\n"
60	      + "order to process an image file.\n"
61	      + "\n"
62	      + "The following image processors are available:\n"
63	      + "  * XML: This processor creates an XML document with all elements of\n"
64	      + "    the fsimage enumerated, suitable for further analysis by XML\n"
65	      + "    tools.\n"
66	      + "  * ReverseXML: This processor takes an XML file and creates a\n"
67	      + "    binary fsimage containing the same elements.\n"
68	      + "  * FileDistribution: This processor analyzes the file size\n"
69	      + "    distribution in the image.\n"
70	      + "    -maxSize specifies the range [0, maxSize] of file sizes to be\n"
71	      + "     analyzed (128GB by default).\n"
72	      + "    -step defines the granularity of the distribution. (2MB by default)\n"
73	      + "    -format formats the output result in a human-readable fashion\n"
74	      + "     rather than a number of bytes. (false by default)\n"
75	      + "  * Web: Run a viewer to expose read-only WebHDFS API.\n"
76	      + "    -addr specifies the address to listen. (localhost:5978 by default)\n"
77	      + "    It does not support secure mode nor HTTPS.\n"
78	      + "  * Delimited (experimental): Generate a text file with all of the elements common\n"
79	      + "    to both inodes and inodes-under-construction, separated by a\n"
80	      + "    delimiter. The default delimiter is \\t, though this may be\n"
81	      + "    changed via the -delimiter argument.\n"
82	      + "    -sp print storage policy, used by delimiter only.\n"
83	      + "  * DetectCorruption: Detect potential corruption of the image by\n"
84	      + "    selectively loading parts of it and actively searching for\n"
85	      + "    inconsistencies. Outputs a summary of the found corruptions\n"
86	      + "    in a delimited format.\n"
87	      + "    Note that the check is not exhaustive, and only catches\n"
88	      + "    missing nodes during the namespace reconstruction.\n"
89	      + "\n"
90	      + "Required command line arguments:\n"
91	      + "-i,--inputFile <arg>   FSImage or XML file to process.\n"
92	      + "\n"
93	      + "Optional command line arguments:\n"
94	      + "-o,--outputFile <arg>  Name of output file. If the specified\n"
95	      + "                       file exists, it will be overwritten.\n"
96	      + "                       (output to stdout by default)\n"
97	      + "                       If the input file was an XML file, we\n"
98	      + "                       will also create an <outputFile>.md5 file.\n"
99	      + "-p,--processor <arg>   Select which type of processor to apply\n"
100	      + "                       against image file. (XML|FileDistribution|\n"
101	      + "                       ReverseXML|Web|Delimited|DetectCorruption)\n"
102	      + "                       The default is Web.\n"
103	      + "-delimiter <arg>       Delimiting string to use with Delimited or \n"
104	      + "                       DetectCorruption processor. \n"
105	      + "-t,--temp <arg>        Use temporary dir to cache intermediate\n"
106	      + "                       result to generate DetectCorruption or\n"
107	      + "                       Delimited outputs. If not set, the processor\n"
108	      + "                       constructs the namespace in memory \n"
109	      + "                       before outputting text.\n"
110	      + "-m,--multiThread <arg> Use multiThread to process sub-sections.\n"
111	      + "-h,--help              Display usage information and exit\n";
112	
113	  /**
114	   * Build command-line options and descriptions
115	   */
116	  private static Options buildOptions() {
117	    Options options = new Options();
118	
119	    // Build in/output file arguments, which are required, but there is no
120	    // addOption method that can specify this
121	    OptionBuilder.isRequired();
122	    OptionBuilder.hasArgs();
123	    OptionBuilder.withLongOpt("inputFile");
124	    options.addOption(OptionBuilder.create("i"));
125	
126	    options.addOption("o", "outputFile", true, "");
127	    options.addOption("p", "processor", true, "");
128	    options.addOption("h", "help", false, "");
129	    options.addOption("maxSize", true, "");
130	    options.addOption("step", true, "");
131	    options.addOption("format", false, "");
132	    options.addOption("addr", true, "");
133	    options.addOption("delimiter", true, "");
134	    options.addOption("sp", false, "");
135	    options.addOption("t", "temp", true, "");
136	    options.addOption("m", "multiThread", true, "");
137	
138	    return options;
139	  }
140	
141	  /**
142	   * Entry point to command-line-driven operation. User may specify options and
143	   * start fsimage viewer from the command line. Program will process image file
144	   * and exit cleanly or, if an error is encountered, inform user and exit.
145	   * 
146	   * @param args
147	   *          Command line options
148	   * @throws IOException
149	   */
150	  public static void main(String[] args) throws Exception {
151	    int status = run(args);
152	    ExitUtil.terminate(status);
153	  }
154	
155	  public static int run(String[] args) throws Exception {
156	    Options options = buildOptions();
157	    if (args.length == 0) {
158	      printUsage();
159	      return 0;
160	    }
161	    // print help and exit with zero exit code
162	    if (args.length == 1 && isHelpOption(args[0])) {
163	      printUsage();
164	      return 0;
165	    }
166	    CommandLineParser parser = new PosixParser();
167	    CommandLine cmd;
168	
169	    try {
170	      cmd = parser.parse(options, args);
171	    } catch (ParseException e) {
172	      System.out.println("Error parsing command-line options: ");
173	      printUsage();
174	      return -1;
175	    }
176	
177	    if (cmd.hasOption("h")) {
178	      // print help and exit with non zero exit code since
179	      // it is not expected to give help and other options together.
180	      printUsage();
181	      return -1;
182	    }
183	
184	    String inputFile = cmd.getOptionValue("i");
185	    String processor = cmd.getOptionValue("p", "Web");
186	    String outputFile = cmd.getOptionValue("o", "-");
187	    String delimiter = cmd.getOptionValue("delimiter",
188	        PBImageTextWriter.DEFAULT_DELIMITER);
189	    String tempPath = cmd.getOptionValue("t", "");
190	    int threads = Integer.parseInt(cmd.getOptionValue("m", "1"));
191	
192	    Configuration conf = new Configuration();
193	    PrintStream out = null;
194	    try {
195	      out = outputFile.equals("-") || "REVERSEXML".equalsIgnoreCase(processor) ?
196	        System.out : new PrintStream(outputFile, "UTF-8");
197	      switch (StringUtils.toUpperCase(processor)) {
198	      case "FILEDISTRIBUTION":
199	        long maxSize = Long.parseLong(cmd.getOptionValue("maxSize", "0"));
200	        int step = Integer.parseInt(cmd.getOptionValue("step", "0"));
201	        boolean formatOutput = cmd.hasOption("format");
202	        try (RandomAccessFile r = new RandomAccessFile(inputFile, "r")) {
203	          new FileDistributionCalculator(conf, maxSize, step, formatOutput, out)
204	            .visit(r);
205	        }
206	        break;
207	      case "XML":
208	        try (RandomAccessFile r = new RandomAccessFile(inputFile, "r")) {
209	          new PBImageXmlWriter(conf, out).visit(r);
210	        }
211	        break;
212	      case "REVERSEXML":
213	        try {
214	          OfflineImageReconstructor.run(inputFile, outputFile);
215	        } catch (Exception e) {
216	          System.err.println("OfflineImageReconstructor failed: "
217	              + e.getMessage());
218	          e.printStackTrace(System.err);
219	          ExitUtil.terminate(1);
220	        }
221	        break;
222	      case "WEB":
223	        String addr = cmd.getOptionValue("addr", "localhost:5978");
224	        try (WebImageViewer viewer =
225	            new WebImageViewer(NetUtils.createSocketAddr(addr), conf)) {
226	          viewer.start(inputFile);
227	        }
228	        break;
229	      case "DELIMITED":
230	        boolean printStoragePolicy = cmd.hasOption("sp");
231	        try (PBImageDelimitedTextWriter writer =
232	            new PBImageDelimitedTextWriter(out, delimiter,
233	                tempPath, printStoragePolicy, threads, outputFile)) {
234	          writer.visit(inputFile);
235	        }
236	        break;
237	      case "DETECTCORRUPTION":
238	        try (PBImageCorruptionDetector detector =
239	            new PBImageCorruptionDetector(out, delimiter, tempPath)) {
240	          detector.visit(inputFile);
241	        }
242	        break;
243	      default:
244	        System.err.println("Invalid processor specified : " + processor);
245	        printUsage();
246	        return -1;
247	      }
248	      return 0;
249	    } catch (EOFException e) {
250	      System.err.println("Input file ended unexpectedly. Exiting");
251	    } catch (IOException e) {
252	      System.err.println("Encountered exception.  Exiting: " + e.getMessage());
253	      e.printStackTrace(System.err);
254	    } finally {
255	      if (out != null && out != System.out) {
256	        out.close();
257	      }
258	    }
259	    return -1;
260	  }
261	
262	  /**
263	   * Print application usage instructions.
264	   */
265	  private static void printUsage() {
266	    System.out.println(usage);
267	  }
268	
269	  private static boolean isHelpOption(String arg) {
270	    return arg.equalsIgnoreCase(HELP_OPT) ||
271	        arg.equalsIgnoreCase(HELP_LONGOPT);
272	  }
273	}
